'use client';
import { useEffect, useState } from 'react';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import toast from 'react-hot-toast';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import type { CampaignInput } from '../types/campaigns.types';
import { cancelCampaign, deleteCampaign, getCampaign, getMediaDownloadUrl, publishCampaign, updateCampaign, uploadCampaignImage } from '../services/campaigns.service';

export function CampaignDetailsDialog({ id, onClose }: { id: string | null; onClose: () => void }) {
  const qc = useQueryClient(); const q = useQuery({ queryKey: ['campaign', id], queryFn: () => getCampaign(id!), enabled: !!id });
  const [edit, setEdit] = useState(false); const [confirm, setConfirm] = useState<'cancel'|'delete'|null>(null); const [form, setForm] = useState<Partial<CampaignInput>>({}); const [image, setImage] = useState<string | null>(null);
  useEffect(() => { if (q.data) { const c=q.data; setForm({name:c.name, description:c.description, startDate:c.startDate, endDate:c.endDate, offerDescription:c.offerDescription, message:c.message, promotionalMediaFileId:c.promotionalMediaFileId}); setEdit(false); } }, [q.data]);
  useEffect(() => { const media=q.data?.promotionalMediaFileId; if (media) void getMediaDownloadUrl(media).then(x=>setImage(x.downloadUrl)).catch(()=>setImage(null)); else setImage(null); }, [q.data?.promotionalMediaFileId]);
  const refresh=(msg:string)=>{toast.success(msg); qc.invalidateQueries({queryKey:['campaigns']}); qc.invalidateQueries({queryKey:['campaign',id]});};
  const save=useMutation({mutationFn:()=>updateCampaign(id!,form),onSuccess:()=>{refresh('Campaign updated');setEdit(false);},onError:fail});
  const publish=useMutation({mutationFn:(s:'SCHEDULED'|'ACTIVE')=>publishCampaign(id!,s),onSuccess:()=>refresh('Campaign published'),onError:fail});
  const cancel=useMutation({mutationFn:()=>cancelCampaign(id!),onSuccess:()=>{setConfirm(null);refresh('Campaign cancelled');},onError:fail});
  const remove=useMutation({mutationFn:()=>deleteCampaign(id!),onSuccess:()=>{toast.success('Campaign deleted');qc.invalidateQueries({queryKey:['campaigns']});onClose();},onError:fail});
  const upload=useMutation({mutationFn:async(file:File)=>updateCampaign(id!,{promotionalMediaFileId:await uploadCampaignImage(q.data!.salonId,file)}),onSuccess:()=>refresh('Promotional image updated'),onError:fail});
  if(!id)return null; const c=q.data; const busy=save.isPending||publish.isPending||cancel.isPending||remove.isPending||upload.isPending; const editable=c?.status==='DRAFT'||c?.status==='SCHEDULED';
  return <div className="fixed inset-0 z-50 flex items-end justify-center bg-black/40 p-4 sm:items-center"><div role="dialog" aria-modal="true" className="app-dialog app-surface-card max-h-[92vh] w-full max-w-2xl overflow-y-auto p-5 shadow-xl">{q.isLoading?<p>Loading campaign…</p>:!c?<p>Could not load campaign.</p>:<><header className="mb-5 flex justify-between"><div><p className="text-xs text-text-secondary">{c.salon.name}</p><h2 className="text-xl font-semibold">{c.name}</h2></div><Button variant="outline" onClick={onClose}>Close</Button></header>{edit?<form className="grid gap-3 panel-md:grid-cols-2" onSubmit={e=>{e.preventDefault();save.mutate();}}><Input required value={form.name??''} onChange={e=>setForm({...form,name:e.target.value})}/><Input placeholder="Offer / discount" value={form.offerDescription??''} onChange={e=>setForm({...form,offerDescription:e.target.value})}/><Input type="datetime-local" value={local(form.startDate)} onChange={e=>setForm({...form,startDate:e.target.value?new Date(e.target.value).toISOString():null})}/><Input type="datetime-local" value={local(form.endDate)} onChange={e=>setForm({...form,endDate:e.target.value?new Date(e.target.value).toISOString():null})}/><Input className="panel-md:col-span-2" placeholder="Message / content" value={form.message??''} onChange={e=>setForm({...form,message:e.target.value})}/><div className="flex gap-2"><Button type="submit" disabled={busy}>Save</Button><Button type="button" variant="outline" onClick={()=>setEdit(false)}>Discard</Button></div></form>:<div className="grid gap-3 text-sm panel-md:grid-cols-2"><Item l="Status" v={c.status}/><Item l="Type" v={c.type}/><Item l="Audience" v={c.targetAudience.replaceAll('_',' ')}/><Item l="Schedule" v={c.startDate&&c.endDate?`${new Date(c.startDate).toLocaleString()} – ${new Date(c.endDate).toLocaleString()}`:'Not scheduled'}/><Item l="Offer" v={c.offerDescription??'—'}/><Item l="Message" v={c.message??'—'}/><Item l="Channels" v={c.deliveryChannels.join(', ')}/><Item l="Description" v={c.description??'—'}/></div>}<section className="mt-5 border-t border-border pt-4"><p className="mb-2 text-sm font-medium">Promotional image</p>{image?<img src={image} alt="Campaign promotional" className="mb-2 h-32 w-full rounded-lg object-cover"/>:<p className="mb-2 text-sm text-text-secondary">No image selected.</p>}{editable?<><input type="file" accept="image/*" disabled={busy} onChange={e=>{const f=e.target.files?.[0];if(f)upload.mutate(f);}}/>{c.promotionalMediaFileId?<Button className="ml-2" variant="outline" onClick={()=>updateCampaign(id,{promotionalMediaFileId:null}).then(()=>refresh('Image removed')).catch(fail)}>Remove image</Button>:null}</>:null}</section><footer className="mt-5 flex flex-wrap gap-2 border-t border-border pt-4">{editable?<Button variant="outline" onClick={()=>setEdit(true)}>Edit</Button>:null}{c.status==='DRAFT'?<><Button disabled={busy} onClick={()=>publish.mutate(c.startDate&&new Date(c.startDate)>new Date()?'SCHEDULED':'ACTIVE')}>{c.startDate&&new Date(c.startDate)>new Date()?'Schedule':'Publish now'}</Button><Button variant="outline" onClick={()=>setConfirm('cancel')}>Cancel campaign</Button><Button variant="outline" onClick={()=>setConfirm('delete')}>Delete</Button></>:null}{c.status==='SCHEDULED'||c.status==='ACTIVE'?<Button variant="outline" onClick={()=>setConfirm('cancel')}>Cancel campaign</Button>:null}</footer>{confirm?<div className="mt-3 rounded-lg border border-warning bg-warning/10 p-3 text-sm">Are you sure you want to {confirm} this campaign?<div className="mt-2 flex gap-2"><Button disabled={busy} onClick={()=>{if(confirm==='cancel')cancel.mutate();else remove.mutate();}}>Confirm</Button><Button variant="outline" onClick={()=>setConfirm(null)}>Keep campaign</Button></div></div>:null}</>}</div></div>;
}
function fail(e:{message?:string}){toast.error(e.message??'Campaign action failed');} function local(v:string|null|undefined){return v?new Date(v).toISOString().slice(0,16):'';} function Item({l,v}:{l:string;v:string}){return <div><p className="text-xs text-text-secondary">{l}</p><p className="whitespace-pre-wrap font-medium">{v}</p></div>;}

